head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.__isShowHeaderFooter = function() {
    var trs = ((j) => j.length ? j : $('#mf_grid1_body_tbody'))($('#grid1_body_tbody')).find("tr").not(".w2grid_hidedRow");
    var numTdHF = scwin.__getJq(trs).find("td.w2grid_groupby_depth_0").length;
    var count = 0;
    trs.each(function() {
        scwin.__getJq(this).find('td').each(function() {
            if (scwin.__getJq(this).hasClass("w2grid_groupby_depth_0")) {
                count++;
            }
        });
    });
    return (trs.length == 9) && (count == numTdHF);
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonObj = [{
        dt: "20140101",
        name: "a",
        accept: "1",
        complete: "1"
    }, {
        dt: "20140101",
        name: "a",
        accept: "1",
        complete: "1"
    }, {
        dt: "20140101",
        name: "b",
        accept: "2",
        complete: "2"
    }, {
        dt: "20140102",
        name: "b",
        accept: "3",
        complete: "3"
    }, {
        dt: "20140102",
        name: "a",
        accept: "4",
        complete: "4"
    }];
    grid1.setJSON(jsonObj);
    window.options = {
        sortIndex: [0],
        sortOrder: [1],
        hideFooter: false,
        hideHeader: false,
        groupbyHeader: {
            depth_0: [{
                colSpan: "3",
                value: "일자별 합계"
            }, {
                inputType: "expression",
                expression: " SUM('complete')",
                className: "aaa"
            }]
        }
    };
    grid1.groupby(options);
}
